\label{sec:prelim}

We introduce some standard notations, following
related work in predictive analyses of concurrent programs~\cite{sen2005detecting,Smaragdakis:2012:SPR:2103621.2103702,conf/pldi/TuncMPV23}.

\label{sec:general-lockset-algo}


\begin{algorithm*}[t!]
  \caption{Computation of \LW\ deadlock patterns.}
  \label{alg:lock-deps}

  {\small
    \begin{algorithmic}[1]
      \Function{computeLWDeadlockPattern}{$T$}
      \label{ln:cLDs}
      \State $\GlobalLHeldT = \emptyset$
        \Comment{Global lock set}
        \label{ln:global-lh}
        \State $\forall t \colon \StdLHeldT(t) = \emptyset$
        \Comment{Standard lock set of thread $t$}
        \label{ln:lh}
        \State $\forall t \colon \threadVC{t} = [\bar{0}]; \incC{\threadVC{t}}{t}$
        \Comment{Vector clock $\threadVC{t}$ of thread $t$}
        \label{ln:thvc}
        \State $\forall x \colon \lastWriteVC{x} = [\bar{0}]$
        \Comment{Vector clocks $\lastWriteVC{x}$ of most recent $\writeE{x}$}
        \label{ln:lwlr}
        \State $\forall l \colon \acqVC{l} = [\bar{0}]$
        \Comment{Vector clock $\acqVC{l}$ of most recent $\acqE{l}$}
        \label{ln:acqv}
        \State $\LDMapSym = \emptyset$
        \Comment{Map  with keys $(t,l,ls)$, value equals a list of vector clocks}
        \label{ln:ld}
        \State $\PList = \emptyset$
        \Comment{List of lock dependencies (t,l,ls,gs) with potential guards $gs$}
        \label{ln:pl}
        \ForDo {$e$ in $T$} {\Call{process}{$e$}}








              \State $DP = \{ (\LDMap{\thread{1}}{l_1}{ls_1}, \ldots, \LDMap{\thread{n}}{l_n}{ls_n}) \mid \forall i \ne j \colon l_i \in ls_{(i \mod n) + 1} \wedge ls_i \indexedcap ls_j = \emptyset \}$
      \label{ln:cyclic-chain}
        \State \Return DP
      \EndFunction
      \algstore{cld}
    \end{algorithmic}

    \begin{minipage}[t]{.52\textwidth}
      \begin{algorithmic}[1]
        \algrestore{cld}
        \Procedure{process}{$(t,acq(l))$}
        \label{ln:procAcq}
        \State $gs = \emptyset$
        \For {$l' \in \GlobalLHeldT \setminus \StdLHeldT(t)$}
        \label{ln:acq-potential-guards}
        \If {$\acqVC{l'} < \threadVC{t}$}
        \label{ln:acq-potential-guards-need-to-be-verified}
        \State $gs = gs \cup \{l'\}$
        \EndIf
        \EndFor
          \If {$gs = \emptyset \wedge \StdLHeldT(t) \not= \emptyset$}
          \State $\LDMap{t}{l}{\StdLHeldT(t)}.push(\threadVC{t})$
          \label{ln:acq-standard-lock-dep}
          \EndIf
          \If {$gs \not= \emptyset$}
          \State $\PList.push((t,l,\threadVC{t},\StdLHeldT(t),gs))$
          \label{ln:acq-possible-guards}
          \EndIf
          \State $\StdLHeldT(t) = \StdLHeldT(t) \cup \{ l \}$
          \State $\GlobalLHeldT = \GlobalLHeldT \cup \{ l \}$
          \label{ln:acq-lh-updates}

          \State $\acqVC{l} = \threadVC{t}$
          \label{ln:acq-store}
          \State $\incC{\threadVC{t}}{t}$
          \label{ln:acq-vc-inc}
        \EndProcedure
        \algstore{eacq}
      \end{algorithmic}
    \end{minipage}

    \hfill

    \begin{minipage}[t]{.44\textwidth}

      \begin{algorithmic}[1]
        \algrestore{eacq}
        \Procedure{process}{$(t,rel(l))$}
        \label{ln:procRel}
        \For {$p@(t', l', V, ls, gs) \in \PList$}
        \label{ln:rel-check-for-guards}
        \If {$l \in gs \wedge V < \threadVC{t}$}
        \State $gs = gs \setminus \{l\}; ls = ls \cup \{l\}$
        \label{ln:rel-guard-verified}
        \EndIf
        \If {$gs = \emptyset$}
        \State $\LDMap{t'}{l'}{ls}.push(V)$
        \State $\PList.erase(p)$
        \EndIf
        \EndFor
          \State $\StdLHeldT(t) = \StdLHeldT(t) \setminus \{ l \}$
          \State $\GlobalLHeldT = \GlobalLHeldT \setminus \{ l \}$
          \label{ln:rel-lh-updates}
          \State $\incC{\threadVC{t}}{t}$
          \label{ln:rel-vc-inc}
        \EndProcedure
        \algstore{erel}
      \end{algorithmic}

    \end{minipage}

    \vspace{.3cm}

    \begin{minipage}[t]{.46\textwidth}
      \begin{algorithmic}[1]
        \algrestore{erel}
        \Procedure{process}{$(t,wr(x))$}
          \label{ln:procWr}
          \State $\lastWriteVC{x} = \threadVC{t}$
          \label{ln:lw-store}
          \State $\incC{\threadVC{t}}{t}$
          \label{ln:wr-vc-inc}
        \EndProcedure
        \algstore{ewr}
      \end{algorithmic}
       \end{minipage}
    \hfill

        \begin{minipage}[t]{.46\textwidth}
      \begin{algorithmic}[1]
        \algrestore{ewr}
        \Procedure{process}{$(t,rd(x))$}
          \label{ln:procRd}
          \State $\threadVC{t} = \threadVC{t} \sqcup \lastWriteVC{x}$
          \State $\incC{\threadVC{t}}{t}$
          \label{ln:rd-vc-inc}
        \EndProcedure
      \end{algorithmic}

    \end{minipage}
  }
\end{algorithm*}

\algdef{SE}[DOWHILE]{Do}{DoWhile}{\algorithmicdo}[1]{\algorithmicwhile\ #1}

\begin{algorithm*}[t]
  \caption{Checking for sync-preserving witness.}
  \label{alg:dp-syncp}

  {\small

    \begin{algorithmic}[1]
      \Function{computeSPDlks}{$T$}
      \label{ln:computeSPDlks}
      \State $DP = \Call{computeLWDeadlockPattern}{T}$
      \label{ln:call-computeDP}
      \State $Dlks = \emptyset$
      \For{$(F_1,\ldots,F_n) \in DP$}
      \If{$\Call{checkSPD}{t_1,F_1,\ldots,t_n,F_n} = (\OK,(V_1,\ldots,V_n))$}
      \label{ln:call-checkSPD}
      \State $Dlks = Dlks \cup \{ \{ V_1,\ldots,V_n \} \}$
      \EndIf
      \EndFor
      \State \Return $Dlks$
      \EndFunction
      \algstore{computeSPDlks}
    \end{algorithmic}

    \begin{minipage}[t]{.56\textwidth}
      \begin{algorithmic}[1]
        \algrestore{computeSPDlks}
        \Function{checkSPD}{$t_1,F_1,\ldots,t_n,F_n$}
        \label{ln:check-spd}
        \State $k_i = 0$ for $i=1,\ldots,n$
        \label{ln:index-init}
        \While{$\bigwedge_{i=1}^n k_i < F_i.size$}
        \label{ln:iterate-through-all}
        \State $V_i = F_i[k_i]$ for $i=1,\ldots,n$
        \label{ln:index-access-vc}
        \State $V'_i = \incC{F_i[k_i]}{t_i}$ for $i=1,\ldots,n$
        \label{ln:vc-of-acquire}
        \State $V = \Call{compSPClosure}{V_1,...,V_n}$
        \label{ln:spclosure}
        \If{$\forall i. V < V'_i$}
        \label{ln:dp-trw-okay}
        \State \Return $(\OK,(V_1,\ldots,V_n))$
        \EndIf
        \State $V = V_1 \sqcup \ldots \sqcup V_n$
        \label{ln:sync-candidates}
        \State $k_i = \Call{next}{V,F_i,k_i}$ for $i=1,\ldots,n$
        \label{ln:next-candidates}
        \EndWhile
        \EndFunction
        \State \Return $(\FAIL,\dontCare)$
        \algstore{checkSPD}
      \end{algorithmic}
    \end{minipage}
    \hfill
    \begin{minipage}[t]{.4\textwidth}

      \begin{algorithmic}[1]
        \algrestore{checkSPD}
        \Function{next}{$V,F,i$}
        \Do
        \State $(\dontCare,V',\dontCare) = F[i]$
        \If{$\neg (V' < V)$}
        \label{ln:next-entry}
        \State \Return $i$
        \EndIf
        \State $i = i + 1$
        \DoWhile{$i < F.size$}
        \State \Return $i$
        \EndFunction
      \end{algorithmic}


    \end{minipage}
  }
\end{algorithm*}


For efficient implementation of partial orders we make use of vector clocks~\cite{Fidge:1991:PAT:646210.683620,Mattern89virtualtime}.
We repeat some standard definitions for vector clocks.

\begin{definition}[Vector Clocks]
  A \emph{vector clock} $V$ is a list of time stamps of the form

  $

    [i_1,\ldots,i_n]
  $.

  We assume vector clocks are of a fixed size $n$.
  \emph{Time stamps} are natural numbers, and a time stamp at position $j$ corresponds to the thread with identifier $\thread{j}$.

  We define

  $
    [i_1,\ldots, i_n] \sqcup [j_1,\ldots,j_n] = [\maxN{i_1}{j_1},\ldots,\maxN{i_n}{j_n}]
  $

  to \emph{synchronize} two vector clocks, taking pointwise-maximal time stamps.

  We write $\incC{V}{j}$ to denote incrementing the vector clock $V$ at position $j$ by one,
  and $\accVC{V}{j}$ to retrieve the time stamp at position $j$.

  We write $V < V'$ if $\forall k \colon \accVC{V}{k} \leq \accVC{V'}{k} \wedge \exists k \colon \accVC{V}{k} < \accVC{V'}{k}$,
  and $V \VCConc V'$ if $V \not< V'$ and $V' \not< V$.
\end{definition}



\cref{alg:lock-deps} computes deadlock patterns based on the $\lwLt[T]$ partial order.
We refer to such deadlock patterns as \emph{\LW\ deadlock patterns}.
In case of deadlock patterns based on the $\roLt[T]$ partial order
the differences only concern the computation of vector clocks.
Something that has been studied extensively~\cite{Smaragdakis:2012:SPR:2103621.2103702,conf/pldi/KiniMV17,10.1145/3360605,conf/mplr/SulzmannS20}.
Hence, we focus on the construction \LW\ deadlock patterns.

Function \textsc{computeLWDeadlockPattern} takes as input
a trace and yields a set of $\LW$ deadlock patterns.
We maintain several state variables when processing events.
For every thread $t$, we have a vector clock~$\threadVC{t}$.
Vector clocks $\lastWriteVC{x}$ represent the last write event on variable~$x$.
Initially, all time stamps are set to zero (\cref{ln:thvc,ln:lwlr,ln:acqv}; $\bar{0}$ denotes a sequence of zeros), and $\threadVC{t}$ is set to 1 at position $t$ (\cref{ln:thvc}).
We use these vector clocks to compute the $\lwLt[T]$ partial order.
See the processing of read (\cref{ln:procRd}) and write (\cref{ln:procWr}) events.

For brevity, we omit explicit request events.
We assume that the vector clock before processing acquire events
implicitly represents requests.

When processing acquire and release events, we maintain two kind of lock sets.
We maintain the standard lock set $\StdLHeldT$ (corresponds to $\LHH{\toLt[T]}$)
and the `global' lock set $\GlobalLHeldT$.
The set $\GlobalLHeldT$ overapproximates the set $\LHH{\lwLt[T]}$.
When processing an acquire, we check for all locks~$l'$
that are not in $\StdLHeldT$ but could be potentially
in $\LHH{\lwLt[T]}$.
Lock~$l'$ is a potential candidate, if the operation that has acquired lock~$l'$
is in a $\LW$ ordering relation with the current acquire of lock~$l$.
To perform this check, we record the vector clock of each
acquire operation (\cref{ln:acq-store}).
We then use this information to check
if $l'$ is a potential candidate in $\LHH{\lwLt[T]}$ (\cref{ln:acq-potential-guards-need-to-be-verified}).
We collect all potential candidates in~$gs$.

If $gs$ is empty and the standard lock set is non-empty,
we can immediately record a (standard) lock dependency (\cref{ln:acq-standard-lock-dep}).
For fast access, we use a map to record lock dependencies.
There may be several acquires that share the same keys.
We store all acquires in a vector using their vector clock as a representative.

If $gs$ is non-empty we add the \emph{potentially guarded}
lock dependency
$
(t,l,\threadVC{t},\StdLHeldT(t),gs)
$

to the list~\PList.
By \emph{potentially guarded} we mean that when processing
the release of any of the potential candidates in $gs$,
we need to verify if the release is in a \LW\ ordering relation
with the current acquire.

When processing a release operation on lock~$l$,
we consult $\PList$ to check if $l$ appears as a potential guard in any $gs$.
For convenience, we make use of set notation when processing list elements.
We use pattern matching notation to refer to element $p$
of shape $(t', l', V, ls, gs)$ (\cref{ln:rel-check-for-guards}).
In our actual implementation, we do not naively iterate over the entire list
but selectively check if a release could be a potential guard.

If the current release is a potential guard, we need to check
that this release is in a $\lwLt[T]$ ordering relation with the prior acquire
that is potentially protected by lock~$l$.
This check can be again carried out via vector clocks.
For each lock dependency $(t', l', ls)$, we also record the vector clock $V$
of the acquire at the time we computed dependency $(t', l', ls)$
and the potential guards $gs$.
Hence, we only need to check if $V < \threadVC{t}$.
If yes, the potential guard could be verified as
an element in $\LHH{\lwLt[T]}$ (\cref{ln:rel-guard-verified}).











Finally, we compute deadlock patterns satisfying
conditions \textbf{DP-Cycle} and \textbf{DP-Guard} (\cref{ln:cyclic-chain}).
We assume thread-indexed lock sets.
Each lock has an attribute to identify the thread from where
the lock results from. For brevity, we omit details.

For efficiency reasons, our representation of deadlock patterns
differs from~\cref{def:deadlock-pattern}.
In~\cref{def:deadlock-pattern}, we represent
a deadlock pattern as a set $\SET{q_1,\dots ,q_n}$ of requests.
In~\cref{sec:general-lockset-algo}, each request $q_i$ is represented
by a vector clock.
We use the vector clock $\threadVC{t}$
before processing of the acquire $(t,acq(l))$ to represent the request.
All (request) vector clocks that are connected to the
same lock dependency $(l,t,ls)$ are stored in a map $\LDMapSym$
where we use $l$,$t$ and $ls$ as keys.
Each value in the map is a list of (request) vector clocks.
Hence, a deadlock pattern is a tuple $(F_1,...,F_n)$
where each $F_i$ refers to a list of vector clocks.
This is referred to as an \emph{abstract} deadlock pattern~\cite{conf/pldi/TuncMPV23}
and simplifies checking for true positives
among instance $(V_1,...,V_n)$ where $V_i$ is an element in $F_i$.

